    (28, "can_enter_fid=false", "El esquema, servicio, API, UI, pruebas y contrato mantienen can_enter_fid=false aun cuando la recomendación esté READY.", "No existe botón Approve Investment ni Enter FID."),
    (29, "Future Investment Gate dependencies", "Un gate futuro deberá aportar autoridad, comité, evidencia financiera, tolerancias, SoD y lifecycle de aprobación propios.", "Gate 07I entrega un handoff, no implementa esas capacidades."),
    (30, "Optional branch behavior", "La configuración permite Budget-only o Resource-only. La rama ausente queda NOT_REQUIRED y la selección procede exclusivamente de la fuente presente.", "false/false permanece inválido."),
    (31, "Funds/FEL boundaries", "No se crean Funds, funding commitments, FEL/PDRI, Project Definition decisions ni autorizaciones de ejecución.", "Límites visibles en overview, ADR, UI y pruebas."),
